import json
from datetime import datetime

def calculate_discount(price, customer_type):
    """Calculate final price based on customer type."""
    if customer_type == "vip":
        discount_rate = 0.9
    elif customer_type == "regular":
        discount_rate = 0.95
    else:
        discount_rate = 1.0

    final_price = price * discount_rate
    return round(final_price, 2)

def generate_order_summary(items, customer_type):
    """Generate a summary dictionary for an order."""
    total = sum(item['price'] * item['quantity'] for item in items)
    final_total = calculate_discount(total, customer_type)

    summary = {
        "order_time": datetime.now().isoformat(),
        "item_count": len(items),
        "original_total": round(total, 2),
        "final_total": final_total,
        "customer_type": customer_type
    }

    return json.dumps(summary, indent=2)
