import csv
from datetime import datetime

def calculate_monthly_sales(data_file):
    """Read sales data from CSV and calculate total sales per month."""
    monthly_sales = {}
    with open(data_file, 'r', encoding='utf-8') as file:
        reader = csv.DictReader(file)
        for row in reader:
            date_str = row.get('date', '')
            amount_str = row.get('amount', '0')
            if not date_str or not amount_str:
                continue
            try:
                sale_date = datetime.strptime(date_str, '%Y-%m-%d')
                amount = float(amount_str)
            except (ValueError, TypeError):
                continue
            key = sale_date.strftime('%Y-%m')
            monthly_sales[key] = monthly_sales.get(key, 0.0) + amount
    return monthly_sales

if __name__ == '__main__':
    results = calculate_monthly_sales('sales_2023.csv')
    for month, total in sorted(results.items()):
        print(f"{month}: {total:.2f}")
