def calculate_discounted_price(price: float, discount_percent: float) -> float:
    """计算折扣后的价格"""
    if price < 0:
        raise ValueError("价格不能为负数")
    if not 0 <= discount_percent <= 100:
        raise ValueError("折扣百分比必须在0到100之间")

    discount_amount = price * (discount_percent / 100)
    final_price = price - discount_amount

    return round(final_price, 2)

def apply_vip_discount(original_price: float, is_vip: bool) -> float:
    """如果是VIP客户，额外享受5%折扣"""
    base_price = calculate_discounted_price(original_price, 10)
    if is_vip:
        final_price = calculate_discounted_price(base_price, 5)
    else:
        final_price = base_price
    return final_price
```

