import csv
import os

def process_sales_data(input_file, output_file):
    """
    Reads sales data from CSV, calculates total revenue per product,
    and writes the summary to a new CSV file.
    """
    if not os.path.exists(input_file):
        print(f"Input file {input_file} not found.")
        return

    revenue_by_product = {}

    try:
        with open(input_file, 'r', newline='', encoding='utf-8') as infile:
            reader = csv.DictReader(infile)
            for row in reader:
                product_name = row.get('product_name')
                quantity = int(row.get('quantity', 0))
                unit_price = float(row.get('unit_price', 0.0))

                if product_name:
                    revenue = quantity * unit_price
                    if product_name in revenue_by_product:
                        revenue_by_product[product_name] += revenue
                    else:
                        revenue_by_product[product_name] = revenue
    except Exception as e:
        print(f"Error reading file: {e}")
        return

    try:
        with open(output_file, 'w', newline='', encoding='utf-8') as outfile:
            writer = csv.writer(outfile)
            writer.writerow(['product_name', 'total_revenue'])
            for product, revenue in sorted(revenue_by_product.items()):
                writer.writerow([product, f"{revenue:.2f}"])
        print(f"Summary written to {output_file}")
    except Exception as e:
        print(f"Error writing file: {e}")

