import json
from datetime import datetime

def process_user_data(user_list):
    """
    Process a list of user dictionaries, calculating total points
    and filtering active users.
    """
    if not user_list:
        return {"total_points": 0, "active_users": []}

    total_points = 0
    active_users = []

    for user in user_list:
        # Ensure required fields exist
        if 'name' not in user or 'points' not in user:
            continue

        try:
            points = int(user['points'])
        except (ValueError, TypeError):
            continue

        total_points += points

        # Check if user is active based on last_login timestamp
        last_login = user.get('last_login')
        if last_login:
            try:
                login_date = datetime.fromisoformat(last_login)
                # Consider user active if login was within last 30 days
                if (datetime.now() - login_date).days <= 30:
                    active_users.append(user['name'])
            except ValueError:
                pass

    return {
        "total_points": total_points,
        "active_users": active_users,
        "processed_at": datetime.now().isoformat()
    }

