        raise FileNotFoundError(f"Config file not found: {file_path}")

    with open(file_path, 'r', encoding='utf-8') as f:
        config = json.load(f)

    # 验证必要字段
    required_keys = ['database', 'api_key', 'timeout']
    for key in required_keys:
