def calculate_discount(price, quantity):
    """Calculate total price with quantity-based discount."""
    if quantity <= 0:
        raise ValueError("Quantity must be positive")

    discount_rate = 0.0
    if quantity >= 100:
        discount_rate = 0.15
    elif quantity >= 50:
        discount_rate = 0.10
    elif quantity >= 20:
        discount_rate = 0.05

    total = price * quantity * (1 - discount_rate)
    return round(total, 2)

def format_order_summary(items):
    """Generate a summary string for order items."""
    lines = ["Order Summary:", "=" * 30]
    for item in items:
        name = item.get('name', 'Unknown')
        qty = item.get('quantity', 0)
        unit_price = item.get('price', 0.0)
        line_total = calculate_discount(unit_price, qty)
        lines.append(f"{name} x{qty}: ${line_total:.2f}")

    total_amount = sum(calculate_discount(i['price'], i['quantity']) for i in items)
    lines.append("-" * 30)
    lines.append(f"Total: ${total_amount:.2f}")
    return "\n".join(lines)
