def calculate_monthly_report(sales_data: list[dict]) -> dict:
    """Calculate total revenue and average order value from sales records."""
    if not sales_data:
        return {"total_revenue": 0.0, "avg_order_value": 0.0, "order_count": 0}

    total_revenue = sum(item["amount"] for item in sales_data)
    order_count = len(sales_data)
    avg_order_value = total_revenue / order_count if order_count > 0 else 0.0

    return {
        "total_revenue": round(total_revenue, 2),
        "avg_order_value": round(avg_order_value, 2),
        "order_count": order_count
    }
