import csv
from datetime import datetime

def process_sales_data(input_file, output_file):
    """读取销售CSV文件，计算每个产品的总销售额并写入新文件"""
    product_totals = {}

    with open(input_file, 'r', newline='', encoding='utf-8') as infile:
        reader = csv.DictReader(infile)
        for row in reader:
            product = row.get('product_name', 'Unknown')
            try:
                amount = float(row.get('amount', 0))
                product_totals[product] = product_totals.get(product, 0) + amount
            except ValueError:
                continue

    with open(output_file, 'w', newline='', encoding='utf-8') as outfile:
        writer = csv.writer(outfile)
        writer.writerow(['product_name', 'total_sales'])
        for product, total in sorted(product_totals.items(), key=lambda x: x[1], reverse=True):
            writer.writerow([product, f"{total:.2f}"])

    return len(product_totals)

if __name__ == "__main__":
    count = process_sales_data("sales_2024.csv", "sales_summary.csv")
    print(f"Processed {count} unique products")
