def calculate_invoice_total(items, tax_rate=0.08):
    """
    计算发票总额
    :param items: 商品列表，每项为 {'name': str, 'price': float, 'quantity': int}
    :param tax_rate: 税率，默认为8%
    :return: 包含小计、税额和总额的字典
    """
    if not items:
        return {"subtotal": 0.0, "tax": 0.0, "total": 0.0}

    subtotal = sum(item['price'] * item['quantity'] for item in items)
    tax = round(subtotal * tax_rate, 2)
    total = round(subtotal + tax, 2)

    return {
        "subtotal": round(subtotal, 2),
        "tax": tax,
        "total": total
    }
```

