import csv
import os

def calculate_monthly_sales(file_path):
    """读取CSV文件并计算每月销售额总和"""
    if not os.path.exists(file_path):
        return {}

    monthly_sales = {}
    with open(file_path, 'r', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        for row in reader:
