import json
from datetime import datetime

def process_order(order_data):
    """处理订单数据并计算总价"""
    if not order_data:
        return {"status": "error", "message": "Empty order"}

    total_price = 0.0
    for item in order_data.get("items", []):
        price = item.get("price", 0)
        quantity = item.get("quantity", 1)
        if price < 0 or quantity < 0:
            return {"status": "error", "message": "Invalid price or quantity"}
        total_price += price * quantity

    discount = order_data.get("discount", 0)
    final_price = max(0, total_price - discount)

    return {
        "status": "success",
        "order_id": order_data.get("id"),
        "total_price": round(total_price, 2),
        "final_price": round(final_price, 2),
        "processed_at": datetime.now().isoformat()
    }

if __name__ == "__main__":
    sample_order = {
        "id": "ORD-12345",
        "items": [
            {"name": "Book", "price": 29.99, "quantity": 2},
            {"name": "Pen", "price": 3.50, "quantity": 5}
        ],
        "discount": 10.00
    }
    result = process_order(sample_order)
    print(json.dumps(result, indent=2))
