                try:
                    sale_date = datetime.strptime(date_str, '%Y-%m-%d')
                    amount = float(amount_str)
                except ValueError:
                    continue

                month_key = sale_date.strftime('%Y-%m')
                total_sales[month_key] = total_sales.get(month_key, 0) + amount
    except FileNotFoundError:
        return {}

    return {k: round(v, 2) for k, v in sorted(total_sales.items())}
